const pptxgen = require('pptxgenjs');

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; 
pres.author = 'Gemini';
pres.title = 'The 2025 LLM Usage Landscape';

// Colors
const colors = {
    darkBlue: "1E2761",
    iceBlue: "CADCFC",
    white: "FFFFFF",
    bgLight: "F8FAFC",
    grayText: "64748B",
    darkText: "0F172A",
    teal: "0D9488",
    mint: "02C39A",
    rose: "E11D48",
    cardBg: "FFFFFF",
    gridLine: "E2E8F0"
};

const makeShadow = () => ({ type: "outer", blur: 6, offset: 3, color: "000000", opacity: 0.1 });

// --- Master Slides ---
pres.defineSlideMaster({
    title: 'COVER',
    background: { color: colors.darkBlue },
    objects: [
        { shape: { x: 0, y: 0, w: 10, h: 0.2, fill: { color: colors.teal } } },
        { shape: { x: 8, y: -2, w: 5, h: 10, fill: { color: "FFFFFF", transparency: 95 }, rotate: 45 } }
    ]
});

pres.defineSlideMaster({
    title: 'CONTENT',
    background: { color: colors.bgLight },
    objects: [
        { shape: { x: 0, y: 0, w: 10, h: 0.1, fill: { color: colors.darkBlue } } },
        { shape: { x: 0, y: 5.2, w: 10, h: 0.5, fill: { color: colors.white } } },
        { text: { text: "Source: OpenRouter Rankings, March 2025", options: { x: 0.5, y: 5.3, w: 5, h: 0.3, fontSize: 10, color: colors.grayText } } },
        { text: { text: "The 2025 LLM Usage Landscape", options: { x: 6, y: 5.3, w: 3.5, h: 0.3, fontSize: 10, color: colors.grayText, align: "right" } } }
    ]
});

// --- Slide 1: Cover ---
let slide1 = pres.addSlide({ masterName: 'COVER' });
slide1.addText("The 2025 LLM Usage Landscape", {
    x: 1, y: 1.8, w: 8, h: 1,
    fontSize: 44, bold: true, color: colors.white, breakLine: true
});
slide1.addText("Real-World Data from OpenRouter", {
    x: 1, y: 2.8, w: 8, h: 0.6,
    fontSize: 28, color: colors.iceBlue
});

slide1.addShape(pres.shapes.RECTANGLE, { x: 1, y: 4, w: 4, h: 0.8, fill: { color: colors.teal }, rectRadius: 0.1 });
slide1.addText("OVER 26T TOKENS", {
    x: 1, y: 4, w: 4, h: 0.45,
    fontSize: 20, bold: true, color: colors.white, align: "center", margin: 0
});
slide1.addText("Processed this week", {
    x: 1, y: 4.45, w: 4, h: 0.3,
    fontSize: 12, color: colors.white, align: "center", margin: 0
});


// --- Slide 2: Top 10 Models ---
let slide2 = pres.addSlide({ masterName: 'CONTENT' });
slide2.addText("This Week's Top 10 Models", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

const tableData = [
    [
        { text: "Rank", options: { bold: true, color: colors.white, fill: { color: colors.darkBlue } } },
        { text: "Model", options: { bold: true, color: colors.white, fill: { color: colors.darkBlue } } },
        { text: "Provider", options: { bold: true, color: colors.white, fill: { color: colors.darkBlue } } },
        { text: "Tokens", options: { bold: true, color: colors.white, fill: { color: colors.darkBlue } } },
        { text: "WoW", options: { bold: true, color: colors.white, fill: { color: colors.darkBlue } } }
    ],
    ["1", { text: "MiMo-V2-Pro", options: { bold: true, color: colors.teal } }, "Xiaomi", "3.96T", { text: "+165%", options: { color: colors.teal, bold: true } }],
    ["2", "Step 3.5 Flash (free)", "Stepfun", "1.49T", "+1%"],
    ["3", "MiniMax M2.7", "MiniMax", "1.29T", { text: "+253%", options: { color: colors.teal, bold: true } }],
    ["4", "DeepSeek V3.2", "DeepSeek", "1.24T", "+9%"],
    ["5", "Claude Sonnet 4.6", "Anthropic", "1.04T", "0%"],
    ["6", "Claude Opus 4.6", "Anthropic", "995B", "+2%"],
    ["7", "Gemini 3 Flash Prev", "Google", "972B", "+3%"],
    ["8", "GLM 5 Turbo", "Zhipu", "968B", { text: "-6%", options: { color: colors.rose } }],
    ["9", "MiniMax M2.5", "MiniMax", "909B", { text: "-30%", options: { color: colors.rose } }],
    ["10", "Grok 4.1 Fast", "x-ai", "599B", "+32%"]
];

slide2.addTable(tableData, {
    x: 0.5, y: 1.2, w: 6.5,
    colW: [0.6, 2.3, 1.3, 1.1, 1.2],
    border: { pt: 1, color: colors.gridLine },
    fontSize: 12,
    align: "center",
    valign: "middle"
});

slide2.addShape(pres.shapes.RECTANGLE, { x: 7.2, y: 1.2, w: 2.3, h: 3.5, fill: { color: colors.white }, shadow: makeShadow() });
slide2.addShape(pres.shapes.RECTANGLE, { x: 7.2, y: 1.2, w: 2.3, h: 0.1, fill: { color: colors.teal } });
slide2.addText("Key Takeaways", { x: 7.4, y: 1.4, w: 1.9, h: 0.4, fontSize: 16, bold: true, color: colors.darkBlue });
slide2.addText([
    { text: "Xiaomi leads by a wide margin with MiMo-V2-Pro.", options: { bullet: true, breakLine: true } },
    { text: "Chinese providers hold 6 of the top 10 spots.", options: { bullet: true, breakLine: true } },
    { text: "MiniMax M2.7 posted the strongest growth (+253%).", options: { bullet: true } }
], { x: 7.4, y: 1.9, w: 1.9, h: 2, fontSize: 12, color: colors.darkText, lineSpacing: 18 });


// --- Slide 3: Provider Market Share Breakdown ---
let slide3 = pres.addSlide({ masterName: 'CONTENT' });
slide3.addText("Provider Market Share Breakdown", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

const pieData = [{
    name: "Market Share",
    labels: ["Xiaomi", "Google", "Anthropic", "MiniMax", "OpenAI", "Stepfun", "DeepSeek", "Zhipu", "Others"],
    values: [25.9, 11.8, 11.0, 8.5, 7.9, 6.8, 6.6, 6.5, 15.0]
}];

slide3.addChart(pres.charts.PIE, pieData, {
    x: 0.5, y: 1.2, w: 5, h: 3.5,
    dataLabelFormatCode: "0.0%",
    showPercent: true,
    showLegend: true,
    legendPos: "r",
    chartColors: ["0D9488", "14B8A6", "5EEAD4", "2563EB", "3B82F6", "60A5FA", "93C5FD", "BFDBFE", "E2E8F0"],
    dataLabelColor: "FFFFFF",
    dataLabelFontSize: 10
});

slide3.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.5, w: 3.5, h: 2.5, fill: { color: colors.white }, shadow: makeShadow() });
slide3.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.5, w: 0.1, h: 2.5, fill: { color: colors.rose } });
slide3.addText("The Rise of Chinese Providers", { x: 6.3, y: 1.7, w: 3, h: 0.4, fontSize: 16, bold: true, color: colors.darkBlue });
slide3.addText("Combined market share of Xiaomi, Stepfun, DeepSeek, MiniMax, and Zhipu now exceeds 54% of total usage on the platform.", {
    x: 6.3, y: 2.2, w: 3, h: 1.5, fontSize: 14, color: colors.darkText, lineSpacing: 20
});

// --- Slide 4: Shifts in the Market Landscape ---
let slide4 = pres.addSlide({ masterName: 'CONTENT' });
slide4.addText("Shifts in the Market Landscape", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

// Fake trend data to visualize "~2T to ~26T"
const trendData = [{
    name: "Weekly Tokens (T)",
    labels: ["Mar '24", "Jun '24", "Sep '24", "Dec '24", "Mar '25"],
    values: [2.1, 5.4, 11.2, 18.5, 26.3]
}];

slide4.addChart(pres.charts.AREA, trendData, {
    x: 0.5, y: 1.2, w: 5, h: 3.5,
    chartColors: ["0D9488"],
    chartArea: { fill: { color: "FFFFFF" } },
    valGridLine: { color: colors.gridLine, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "t",
    dataLabelColor: colors.darkText,
    showLegend: false,
    lineSmooth: true
});

slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.2, w: 3.5, h: 1, fill: { color: colors.white }, shadow: makeShadow() });
slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.2, w: 0.08, h: 1, fill: { color: colors.teal } });
slide4.addText([
    { text: "Explosive Overall Growth\n", options: { bold: true, fontSize: 14, color: colors.darkBlue } },
    { text: "Total market has expanded from ~2T to over ~26T tokens weekly.", options: { fontSize: 12, color: colors.darkText } }
], { x: 6.2, y: 1.2, w: 3.2, h: 1, margin: 0.1 });

slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 2.4, w: 3.5, h: 1, fill: { color: colors.white }, shadow: makeShadow() });
slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 2.4, w: 0.08, h: 1, fill: { color: colors.teal } });
slide4.addText([
    { text: "Flash/Turbo Domination\n", options: { bold: true, fontSize: 14, color: colors.darkBlue } },
    { text: "Fast and affordable variants far outpace flagship models in real-world use.", options: { fontSize: 12, color: colors.darkText } }
], { x: 6.2, y: 2.4, w: 3.2, h: 1, margin: 0.1 });

slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 3.6, w: 3.5, h: 1, fill: { color: colors.white }, shadow: makeShadow() });
slide4.addShape(pres.shapes.RECTANGLE, { x: 6, y: 3.6, w: 0.08, h: 1, fill: { color: colors.teal } });
slide4.addText([
    { text: "Anthropic's Stalled Growth\n", options: { bold: true, fontSize: 14, color: colors.darkBlue } },
    { text: "Despite two models in the Top 10, total growth has leveled off.", options: { fontSize: 12, color: colors.darkText } }
], { x: 6.2, y: 3.6, w: 3.2, h: 1, margin: 0.1 });

// --- Slide 5: This Week's Rising Stars ---
let slide5 = pres.addSlide({ masterName: 'CONTENT' });
slide5.addText("This Week's Rising Stars: Fastest-Growing Models", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

const addStarCard = (x, y, model, provider, growth, insight) => {
    slide5.addShape(pres.shapes.RECTANGLE, { x: x, y: y, w: 2.8, h: 3, fill: { color: colors.white }, shadow: makeShadow() });
    slide5.addShape(pres.shapes.RECTANGLE, { x: x, y: y, w: 2.8, h: 0.1, fill: { color: colors.teal } });
    slide5.addText(growth, { x: x, y: y + 0.3, w: 2.8, h: 0.8, fontSize: 40, bold: true, color: colors.teal, align: "center", margin: 0 });
    slide5.addText(model, { x: x, y: y + 1.2, w: 2.8, h: 0.4, fontSize: 18, bold: true, color: colors.darkBlue, align: "center", margin: 0 });
    slide5.addText(provider, { x: x, y: y + 1.6, w: 2.8, h: 0.3, fontSize: 12, color: colors.grayText, align: "center", margin: 0 });
    slide5.addShape(pres.shapes.LINE, { x: x + 0.4, y: y + 2, w: 2, h: 0, line: { color: colors.gridLine, width: 1 } });
    slide5.addText(insight, { x: x + 0.2, y: y + 2.1, w: 2.4, h: 0.8, fontSize: 11, color: colors.darkText, align: "center", margin: 0 });
};

addStarCard(0.5, 1.5, "MiniMax M2.7", "MiniMax", "+253%", "Huge spike driven by cost-effective context processing and expanded availability.");
addStarCard(3.6, 1.5, "MiMo-V2-Pro", "Xiaomi", "+165%", "Cemented #1 spot with dominant overall volume, leveraging strong ecosystem usage.");
addStarCard(6.7, 1.5, "Cline", "Independent", "+128%", "Rapid adoption among developers as autonomous coding agents hit the mainstream.");


// --- Slide 6: App Ecosystem ---
let slide6 = pres.addSlide({ masterName: 'CONTENT' });
slide6.addText("App Ecosystem: Who's Calling These Models", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

const appData = [
    { name: "OpenClaw", desc: "AI productivity assistant", tokens: "829B", isCode: true },
    { name: "Kilo Code", desc: "VS Code AI coding assistant", tokens: "271B", isCode: true },
    { name: "Claude Code", desc: "Anthropic's CLI coding tool", tokens: "78B", isCode: true },
    { name: "Cline", desc: "VS Code autonomous coding agent", tokens: "69.1B", isCode: true },
    { name: "Janitor AI", desc: "Character roleplay chat", tokens: "29.2B", isCode: false }
];

slide6.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 5, h: 3.5, fill: { color: colors.white }, shadow: makeShadow() });
slide6.addText("Top Apps by Daily Token Consumption", { x: 0.8, y: 1.4, w: 4.4, h: 0.4, fontSize: 16, bold: true, color: colors.darkBlue });

let curY = 1.9;
appData.forEach((app, i) => {
    slide6.addText(`${i+1}. ${app.name}`, { x: 0.8, y: curY, w: 2.5, h: 0.3, fontSize: 14, bold: true, color: app.isCode ? colors.teal : colors.darkText, margin: 0 });
    slide6.addText(app.tokens, { x: 3.5, y: curY, w: 1.5, h: 0.3, fontSize: 14, bold: true, color: colors.darkBlue, align: "right", margin: 0 });
    slide6.addText(app.desc, { x: 0.8, y: curY + 0.3, w: 4.2, h: 0.2, fontSize: 11, color: colors.grayText, margin: 0 });
    if(i < appData.length - 1) {
        slide6.addShape(pres.shapes.LINE, { x: 0.8, y: curY + 0.6, w: 4.4, h: 0, line: { color: colors.gridLine, width: 0.5 } });
    }
    curY += 0.55;
});

slide6.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.2, w: 3.5, h: 3.5, fill: { color: colors.darkBlue }, shadow: makeShadow() });
slide6.addText("The Era of Coding Agents", { x: 6.3, y: 1.5, w: 2.9, h: 0.4, fontSize: 20, bold: true, color: colors.white });
slide6.addText([
    { text: "Developer tools dominate:\n", options: { bold: true, color: colors.teal } },
    { text: "The top 4 apps are all AI coding tools or productivity agents.\n\n" },
    { text: "Largest consumption scenario:\n", options: { bold: true, color: colors.teal } },
    { text: "AI coding assistants are now the single largest driver of LLM usage.\n\n" },
    { text: "OpenClaw outlier:\n", options: { bold: true, color: colors.teal } },
    { text: "Consumes nearly 3x the tokens of the second-place app (829B/day)." }
], { x: 6.3, y: 2.1, w: 2.9, h: 2.4, fontSize: 13, color: colors.iceBlue, lineSpacing: 18 });


// --- Slide 7: Key Insights and Industry Implications ---
let slide7 = pres.addSlide({ masterName: 'CONTENT' });
slide7.addText("Key Insights and Industry Implications", { x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 28, bold: true, color: colors.darkBlue });

const addInsightCard = (x, y, num, title, desc) => {
    slide7.addShape(pres.shapes.RECTANGLE, { x: x, y: y, w: 4.2, h: 1.5, fill: { color: colors.white }, shadow: makeShadow() });
    slide7.addShape(pres.shapes.RECTANGLE, { x: x, y: y, w: 0.4, h: 1.5, fill: { color: colors.teal } });
    slide7.addText(num, { x: x, y: y, w: 0.4, h: 1.5, fontSize: 20, bold: true, color: colors.white, align: "center", valign: "middle", margin: 0 });
    slide7.addText(title, { x: x + 0.6, y: y + 0.2, w: 3.4, h: 0.4, fontSize: 16, bold: true, color: colors.darkBlue, margin: 0 });
    slide7.addText(desc, { x: x + 0.6, y: y + 0.65, w: 3.4, h: 0.7, fontSize: 12, color: colors.darkText, lineSpacing: 16, margin: 0 });
};

addInsightCard(0.5, 1.3, "1", "Chinese Models Dominant", "Models from providers like Xiaomi, DeepSeek, and MiniMax now hold a decisive >54% share of the global platform.");
addInsightCard(5.3, 1.3, "2", "Coding Agents Rule", "AI coding tools form the single largest usage category, representing the most concrete commercial value proposition.");
addInsightCard(0.5, 3.2, "3", "Market Highly Fragmented", "The top 10 spans 8 different providers. No single entity holds a monopoly, pointing to ongoing fierce competition.");
addInsightCard(5.3, 3.2, "4", "Fast & Affordable Win", "Flash/Turbo variants consistently outpace flagship models in usage, proving cost and speed matter most in production.");

// Save the presentation
pres.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(fileName => {
    console.log(`created file: ${fileName}`);
}).catch(err => {
    console.error(err);
});

